/**
 * The lint engine's low-level pieces give the same answers in WASM as natively.
 *
 * The YAML layer, CEL parser and evaluator, regex engine and rule loader are reached
 * through private test hooks that return JSON text (`wasm/bindings.cpp`,
 * `_lint*`). The expectations are generated by running the native hooks over
 * the same inputs (`scripts/gen-lintcore-parity-fixture.py`), and compared as
 * text: decoding first would lose int64 precision and hide formatting drift.
 */
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { beforeAll, describe, expect, it } from 'vitest';
import { initPssParser } from '../src/index.js';

interface FixtureCase {
  id: string;
  fn: 'YamlLoad' | 'YamlSourceMaps' | 'YamlCelParse' | 'CelParse' | 'CelEval' | 'CelFunctions' | 'CelCheck' | 'RegexSearch' | 'ReflectSchema' | 'RuleLoad';
  args: Array<string | number | null>;
  /** When set, the last argument (or argument `fileArg`) is this repository file's text. */
  file?: string;
  fileArg?: number;
  out?: string;
  sha256?: string;
  len?: number;
}

interface FixtureBatch {
  id: string;
  fn: FixtureCase['fn'];
  extra: Array<string | number>;
  sha256: string;
  /**
   * The inputs; or `source`, a committed conformance file whose tests' `expr`
   * are; or `inputsOf`, the id of an earlier batch with the inputs.
   */
  inputs?: string[];
  source?: string;
  inputsOf?: string;
  /** Arguments passed before each input. */
  lead?: string[];
  /** Each input is passed as the JSON document `{...wrapWith, [wrap]: input}`. */
  wrap?: string;
  wrapWith?: Record<string, unknown>;
}

/** The private hooks; not part of PssParserModule on purpose. */
type Hooks = Record<`_lint${FixtureCase['fn']}`, (...args: Array<string | number>) => string>;

const here = dirname(fileURLToPath(import.meta.url));
const fixturePath = join(here, 'fixtures', 'lintcore-parity.json');
const repoRoot = join(here, '..', '..');
const fixture = JSON.parse(readFileSync(fixturePath, 'utf8')) as {
  cases: FixtureCase[];
  batches: FixtureBatch[];
};

let hooks: Hooks;
beforeAll(async () => {
  hooks = (await initPssParser()) as unknown as Hooks;
});

describe('lint engine parity with the native build', () => {
  it.each(fixture.cases.map((c) => [c.id, c] as const))('%s', (_id, c) => {
    const fileArg = c.fileArg ?? c.args.length - 1;
    const args = c.args.map((a, i) =>
      c.file !== undefined && i === fileArg ? readFileSync(join(repoRoot, c.file), 'utf8') : a
    ) as Array<string | number>;
    const got = hooks[`_lint${c.fn}`](...args);
    if (c.out !== undefined) {
      expect(got).toBe(c.out);
    } else {
      const b = Buffer.from(got, 'utf8');
      expect({ len: b.length, sha256: createHash('sha256').update(b).digest('hex') }).toEqual({
        len: c.len,
        sha256: c.sha256,
      });
    }
  });

  it.each(fixture.batches.map((b) => [b.id, b] as const))('batch %s', (_id, b) => {
    const inputs =
      b.inputs ??
      fixture.batches.find((o) => o.id === b.inputsOf)?.inputs ??
      (JSON.parse(readFileSync(join(repoRoot, b.source as string), 'utf8')) as {
        tests: Array<{ expr: string }>;
      }).tests.map((t) => t.expr);
    const h = createHash('sha256');
    for (const x of inputs) {
      const input = b.wrap !== undefined ? JSON.stringify({ ...b.wrapWith, [b.wrap]: x }) : x;
      h.update(Buffer.from(hooks[`_lint${b.fn}`](...(b.lead ?? []), input, ...b.extra), 'utf8'));
      h.update(Buffer.from([0]));
    }
    // A mismatch says only that some input in the batch differs: run the
    // batch's inputs through both builds one by one to find it.
    expect(h.digest('hex')).toBe(b.sha256);
  });

  it('covers every hook', () => {
    expect(new Set(fixture.cases.map((c) => c.fn))).toEqual(
      new Set(['YamlLoad', 'YamlSourceMaps', 'YamlCelParse', 'CelParse', 'CelEval', 'CelFunctions', 'CelCheck', 'RegexSearch', 'ReflectSchema', 'RuleLoad'])
    );
  });
});
